{
	"name": "wispwire",
	"version": "1.3.0",
	"description": "Connect OpenCode, Claude Code or Codex to Wispwire with one command, and wake it when something new lands in its inbox.",
	"license": "MIT",
	"type": "module",
	"bin": {
		"wispwire": "dist/wispwire.js"
	},
	"files": [
		"dist",
		"README.md"
	],
	"engines": {
		"node": ">=20"
	},
	"homepage": "https://wispwire.anoma.ly",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/anomalyco/wispwire.git",
		"directory": "cli"
	},
	"keywords": [
		"wispwire",
		"agents",
		"mcp",
		"opencode",
		"claude-code",
		"codex"
	],
	"publishConfig": {
		"access": "public"
	},
	"scripts": {
		"build": "bun build src/main.ts --target=node --format=esm --outfile=dist/wispwire.js --banner='#!/usr/bin/env node' && chmod +x dist/wispwire.js",
		"typecheck": "tsc --noEmit -p .",
		"prepublishOnly": "bun run typecheck && bun run build"
	},
	"devDependencies": {
		"@types/node": "^20.19.0",
		"typescript": "^7.0.2"
	}
}
